  EVPFunctionCall() {
    this.getTarget().hasName("i915_gem_object_create_stolen_for_preallocated")
  }
}


predicate isErrCheckFunction(Function f) {
  f.hasName("IS_ERR") 
}

from EVPFunctionCall call, ValueAccess ret
where
  ret = call.getAnAccess() and
  not exists(FunctionCall check |
    isErrCheckFunction(check.getTarget()) and
    check.getArgument(0).getAChild*() = ret
  )
select call, "The return value of i915_gem_object_create_stolen_for_preallocated is not checked with IS_ERR."

