 {
 fc.getTarget().hasName("free")
or fc.getTarget().hasName("pcap_close")
or fc.getTarget().hasName("pcap_freecode")
or fc.getTarget().hasName("pcap_freealldevs")
or fc.getTarget().hasName("pcap_dump_close")
